// Conceptual architecture (Go)
type Agent struct {
    mcp    *mcpclient.Client  // MCP: tool access
    pilot  *driver.Driver     // Pilot: peer networking
    llm    *llmclient.Client  // LLM: reasoning
}

// The agent loop: accept a request, gather data, reason, reply
func (a *Agent) Run() {
    ln, _ := a.pilot.Listen(1000)
    for {
        conn, _ := ln.Accept()
        req := readRequest(conn)

        // 1. Use MCP to gather data
        data := a.mcp.CallTool("database_query", req.Params)

        // 2. Use LLM to reason about the data
        result := a.llm.Complete(req.Prompt + data)

        // 3. Use Pilot to deliver the result on the same connection
        conn.Write([]byte(result))
        conn.Close()
    }
}

package main

import (
    "encoding/json"
    "fmt"
    "log"

    "github.com/pilot-protocol/common/driver"
    "github.com/pilot-protocol/common/protocol"
    "github.com/pilot-protocol/eventstream"
)

func main() {
    // Connect to the local Pilot daemon
    drv, err := driver.Connect("/tmp/pilot.sock")
    if err != nil {
        log.Fatal(err)
    }
    defer drv.Close()

    // Accept research requests on port 1000
    ln, err := drv.Listen(1000)
    if err != nil {
        log.Fatal(err)
    }

    // Completion events go to a hub node's event stream (port 1002).
    // Other agents follow them with: pilotctl subscribe research-hub research.completed
    hub, err := drv.ResolveHostname("research-hub")
    if err != nil {
        log.Fatal(err)
    }
    hubAddr, err := protocol.ParseAddr(hub["address"].(string))
    if err != nil {
        log.Fatal(err)
    }
    events, err := eventstream.Subscribe(drv, hubAddr, "research.completed")
    if err != nil {
        log.Fatal(err)
    }
    defer events.Close()

    log.Println("Research agent online, waiting for requests...")

    for {
        // Accept an incoming research request via Pilot
        conn, err := ln.Accept()
        if err != nil {
            log.Printf("accept error: %v", err)
            continue
        }

        buf := make([]byte, 64*1024)
        n, err := conn.Read(buf)
        if err != nil {
            conn.Close()
            continue
        }
        var req map[string]string
        if err := json.Unmarshal(buf[:n], &req); err != nil {
            conn.Close()
            continue
        }
        log.Printf("Received request from %s", conn.RemoteAddr())

        // Use MCP to query the database
        queryResult := callMCPTool("database", "query", map[string]string{
            "sql": fmt.Sprintf(
                "SELECT title, abstract FROM papers WHERE topic LIKE '%%%s%%' LIMIT 10",
                req["topic"],
            ),
        })

        // Use MCP to fetch web content for additional context
        webResult := callMCPTool("web-search", "search", map[string]string{
            "query": req["topic"] + " recent developments",
        })

        // Combine sources and produce summary (LLM call omitted for clarity)
        summary := fmt.Sprintf(
            "Research summary for: %s\n\nDatabase:\n%s\n\nWeb: %s",
            req["topic"], queryResult, webResult,
        )

        // Return results to the requester on the same connection
        if _, err := conn.Write([]byte(summary)); err != nil {
            log.Printf("write error: %v", err)
        }
        conn.Close()

        // Publish an event so other agents know the research is done
        eventData, _ := json.Marshal(map[string]string{"topic": req["topic"]})
        if err := events.Publish("research.completed", eventData); err != nil {
            log.Printf("publish error: %v", err)
        }
    }
}

